// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 개인정보 수정 (21번)" (7eba581395294d21a1525153ae058ecd).
// REQ-MYPAGE-003: 아이디 확인, 현재 비밀번호 확인 후 비밀번호·전화번호 변경 (#29)
import { useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorCode, getErrorMessage, getFieldErrors } from "../api/client";
import { getMyInfo, updatePrivate, type MyInfo, type PrivateUpdateRequest } from "../api/mypage";
import Header from "../components/Header";
import { useAuth } from "../hooks/useAuth";
import "./AccountEdit.css";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  "body {\n      background-color: #FFFDF5;\n      background-image: radial-gradient(#D9D4C3 1px, transparent 1px);\n      background-size: 18px 18px;\n    }\n  \n\n    /* Neo-brutalist custom utilities */\n    .neo-box {\n      border: 2.5px solid #111111;\n      border-radius: 12px;\n      box-shadow: 5px 5px 0px #111111;\n    }\n    .neo-input {\n      border: 2.5px solid #111111;\n      border-radius: 10px;\n      transition: all 0.15s ease-in-out;\n    }\n    .neo-input:focus {\n      outline: none;\n      box-shadow: 3px 3px 0px #111111;\n    }\n    .neo-btn {\n      border: 2.5px solid #111111;\n      box-shadow: 3px 3px 0px #111111;\n      transition: transform 0.1s ease, box-shadow 0.1s ease;\n    }\n    .neo-btn:hover {\n      transform: translate(-1px, -1px);\n      box-shadow: 4px 4px 0px #111111;\n    }\n    .neo-btn:active {\n      transform: translate(2px, 2px);\n      box-shadow: 1px 1px 0px #111111;\n    }";

// 서버(member.constants.js)와 같은 입력값 규칙 (docs/api.md 입력값 규칙)
const PASSWORD_PATTERN = /^[A-Za-z0-9_.-]{8,12}$/;
const PHONE_PATTERN = /^01[0-9]{8,9}$/;

type Field = "currentPassword" | "newPassword" | "passwordConfirm" | "phone";
type Errors = Partial<Record<Field | "form", string>>;

const SERVER_FIELDS: Record<string, Field> = {
  currentPassword: "currentPassword",
  newPassword: "newPassword",
  phone: "phone",
};

// 01012345678 → 010-1234-5678, 0101234567 → 010-123-4567 (입력 중에도 자동으로 하이픈을 넣는다)
function formatPhone(value: string) {
  const digits = value.replace(/\D/g, "").slice(0, 11);
  if (digits.length < 4) return digits;
  if (digits.length < 8) return `${digits.slice(0, 3)}-${digits.slice(3)}`;
  const middle = digits.length === 11 ? 4 : 3;
  return `${digits.slice(0, 3)}-${digits.slice(3, 3 + middle)}-${digits.slice(3 + middle)}`;
}

// 2026-11-01T10:00:00 → 2026.11.01
function formatDate(value: string) {
  return value.slice(0, 10).replaceAll("-", ".");
}

function validate(
  values: Record<Field, string>,
  currentPhone: string,
): { errors: Errors; request?: PrivateUpdateRequest } {
  const errors: Errors = {};
  const phone = values.phone.replace(/-/g, "");
  const changingPassword = values.newPassword !== "" || values.passwordConfirm !== "";
  const changingPhone = phone !== currentPhone;

  if (values.currentPassword === "") {
    errors.currentPassword = "저장하려면 현재 비밀번호를 입력해주세요.";
  }
  if (!PHONE_PATTERN.test(phone)) {
    errors.phone = "01로 시작하는 10~11자리 숫자로 입력해주세요.";
  }
  if (changingPassword) {
    if (!PASSWORD_PATTERN.test(values.newPassword)) {
      errors.newPassword = "8~12자, 영문·숫자와 특수기호 _ . - 만 사용할 수 있어요.";
    } else if (values.newPassword !== values.passwordConfirm) {
      errors.passwordConfirm = "새 비밀번호와 일치하지 않아요.";
    }
  }
  if (!changingPassword && !changingPhone && !errors.phone) {
    errors.form = "변경할 내용이 없어요. 새 비밀번호나 전화번호를 입력해주세요.";
  }
  if (Object.keys(errors).length > 0) {
    return { errors };
  }
  return {
    errors,
    request: {
      currentPassword: values.currentPassword,
      ...(changingPassword && { newPassword: values.newPassword }),
      ...(changingPhone && { phone }),
    },
  };
}

function ErrorText({ children }: { children?: ReactNode }) {
  if (!children) return null;
  return (
    <p className="text-[11px] font-semibold mt-1.5 flex items-center gap-1 text-rose-600" role="alert">
      <span aria-hidden="true">⚠</span>
      {children}
    </p>
  );
}

function EyeIcon({ open }: { open: boolean }) {
  return (
    <svg
      className="h-4 w-4 eye-icon"
      fill="none"
      stroke="currentColor"
      viewBox="0 0 24 24"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>
      <path
        d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth="2"
      ></path>
      {!open && <path d="M3 3l18 18" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"></path>}
    </svg>
  );
}

// 비밀번호 입력칸 (숨김 상태가 기본, 눈 아이콘으로 표시/숨김 전환)
function PasswordField(props: {
  id: string;
  label: string;
  placeholder: string;
  value: string;
  error?: string;
  autoComplete: string;
  onChange: (value: string) => void;
}) {
  const [visible, setVisible] = useState(false);
  return (
    <div className="grid grid-cols-1 sm:grid-cols-12 gap-2 sm:gap-3 items-start">
      <label className="sm:col-span-4 text-sm font-bold text-gray-800 sm:pt-2.5" htmlFor={props.id}>
        {props.label}
      </label>
      <div className="sm:col-span-8">
        <div className="relative">
          <input
            aria-invalid={Boolean(props.error)}
            autoComplete={props.autoComplete}
            className={`w-full neo-input bg-white text-sm px-3.5 py-2.5 pr-10 focus:bg-amber-50/30 font-mono tracking-wider ${
              props.error ? "border-rose-600" : ""
            }`}
            id={props.id}
            onChange={(e) => props.onChange(e.target.value)}
            placeholder={props.placeholder}
            type={visible ? "text" : "password"}
            value={props.value}
          />
          <button
            aria-label={visible ? "비밀번호 숨기기" : "비밀번호 표시"}
            className="absolute inset-y-0 right-0 px-3 flex items-center text-gray-500 hover:text-black focus:outline-none"
            onClick={() => setVisible((v) => !v)}
            type="button"
          >
            <EyeIcon open={visible} />
          </button>
        </div>
        <ErrorText>{props.error}</ErrorText>
      </div>
    </div>
  );
}

// 변경 완료 알림 (REQ-MYPAGE-003 "변경 완료 시 알림")
function CompleteDialog({ onClose }: { onClose: () => void }) {
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 backdrop-blur-[8px]"
      style={{ backgroundColor: "rgba(255, 253, 245, 0.55)" }}
    >
      <section
        aria-labelledby="account-edit-complete-title"
        aria-modal="true"
        className="neo-box w-full max-w-sm bg-white p-8 text-center"
        role="dialog"
      >
        <div className="w-14 h-14 rounded-full bg-emerald-100 text-emerald-600 border-[2.5px] border-black mx-auto mb-5 flex items-center justify-center">
          <svg className="w-8 h-8" fill="none" stroke="currentColor" strokeWidth={3} viewBox="0 0 24 24">
            <path d="M5 13l4 4L19 7" strokeLinecap="round" strokeLinejoin="round"></path>
          </svg>
        </div>
        <h2 className="text-xl font-black mb-2" id="account-edit-complete-title">
          개인정보가 변경되었습니다
        </h2>
        <p className="text-sm text-gray-600 font-medium mb-6">변경한 내용은 바로 적용돼요.</p>
        <button
          autoFocus
          className="neo-btn w-full py-2.5 bg-[#FFD43B] font-extrabold text-sm rounded-lg cursor-pointer hover:bg-yellow-400"
          onClick={onClose}
          type="button"
        >
          확인
        </button>
      </section>
    </div>
  );
}

const EMPTY_VALUES: Record<Field, string> = { currentPassword: "", newPassword: "", passwordConfirm: "", phone: "" };

export default function AccountEdit() {
  const navigate = useNavigate();
  const { user, initializing } = useAuth();
  const [me, setMe] = useState<MyInfo | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [values, setValues] = useState(EMPTY_VALUES);
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);
  const [completed, setCompleted] = useState(false);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  useEffect(() => {
    if (!user) return;
    let cancelled = false;
    getMyInfo()
      .then((info) => {
        if (cancelled) return;
        setMe(info);
        setValues({ ...EMPTY_VALUES, phone: formatPhone(info.phone) });
      })
      .catch((error) => {
        if (!cancelled) setLoadError(getErrorMessage(error, "내 정보를 불러오지 못했습니다."));
      });
    return () => {
      cancelled = true;
    };
  }, [user]);

  const change = (field: Field) => (value: string) => {
    setValues((prev) => ({ ...prev, [field]: field === "phone" ? formatPhone(value) : value }));
    setErrors((prev) => ({ ...prev, [field]: undefined, form: undefined }));
  };

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!me || submitting) return;
    const { errors: found, request } = validate(values, me.phone);
    setErrors(found);
    if (!request) return;

    setSubmitting(true);
    try {
      await updatePrivate(request);
      setMe({ ...me, phone: request.phone ?? me.phone });
      setValues((prev) => ({ ...EMPTY_VALUES, phone: prev.phone }));
      setCompleted(true);
    } catch (error) {
      const code = getErrorCode(error);
      if (code === "PASSWORD_MISMATCH") {
        setErrors({ currentPassword: "현재 비밀번호가 일치하지 않아요." });
      } else if (code === "DUPLICATE_PHONE") {
        setErrors({ phone: "이미 가입된 전화번호예요." });
      } else if (code === "INVALID_INPUT") {
        const next: Errors = {};
        getFieldErrors(error).forEach(({ field, reason }) => {
          next[SERVER_FIELDS[field] ?? "form"] = reason;
        });
        setErrors(Object.keys(next).length > 0 ? next : { form: getErrorMessage(error) });
      } else {
        setErrors({ form: getErrorMessage(error) });
      }
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div id="page-account-edit">
      <style>{css}</style>
      <div className="min-h-screen font-sans text-neo-black flex flex-col">
        {/* BEGIN: MainContent */}
        <Header />
        <main className="w-full max-w-4xl mx-auto px-4 py-8 md:py-10" data-purpose="profile-edit-container">
          {/* BEGIN: TopBar */}
          <header className="flex items-center justify-between mb-6 pb-2" data-purpose="header-section">
            <div className="flex items-center gap-3">
              <div className="w-3 h-7 bg-neo-black rounded-sm"></div>
              <h1 className="text-[22px] font-[800] tracking-tight leading-none">개인정보 수정</h1>
            </div>
            <Link
              className="neo-btn inline-flex items-center gap-1.5 px-4 py-2 bg-white text-sm font-bold rounded-lg cursor-pointer"
              to="/mypage"
            >
              <svg
                className="w-4 h-4 stroke-[2.5]"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path d="M10.5 19.5L3 12m0 0l7.5-7.5M3 12h18" strokeLinecap="round" strokeLinejoin="round"></path>
              </svg>{" "}
              <span>마이페이지</span>
            </Link>
          </header>
          {/* END: TopBar */}

          {loadError && (
            <div className="neo-box bg-rose-50 p-4 mb-6 text-sm font-bold text-rose-700" role="alert">
              {loadError}
            </div>
          )}
          {!me && !loadError && <p className="text-sm font-semibold text-gray-500">내 정보를 불러오는 중이에요…</p>}

          {me && (
            <form className="space-y-6" id="profile-edit-form" noValidate onSubmit={handleSubmit}>
              {/* BEGIN: AccountInfoSection */}
              <section className="neo-box bg-[#F9F7F1] p-6 transition-all" data-purpose="account-identity-section">
                <div className="space-y-4">
                  {/* 아이디 (수정 불가) */}
                  <div className="grid grid-cols-1 sm:grid-cols-12 gap-2 sm:gap-4 items-center">
                    <label className="sm:col-span-2 text-sm font-bold text-gray-800" htmlFor="username">
                      아이디
                    </label>
                    <div className="sm:col-span-6">
                      <input
                        className="w-full neo-input bg-neo-disabled font-mono text-sm px-3.5 py-2.5 text-gray-600 cursor-not-allowed border-dashed select-none"
                        disabled
                        id="username"
                        type="text"
                        value={`${me.loginId} (수정 불가)`}
                      />
                    </div>
                  </div>
                  {/* 가입일 */}
                  <div className="grid grid-cols-1 sm:grid-cols-12 gap-2 sm:gap-4 items-center">
                    <span className="sm:col-span-2 text-sm font-bold text-gray-800">가입일</span>
                    <div className="sm:col-span-6 font-mono font-medium text-sm text-gray-700 pl-1">
                      {formatDate(me.createdAt)}
                    </div>
                  </div>
                </div>
              </section>
              {/* END: AccountInfoSection */}

              {/* BEGIN: ContactSection */}
              <section className="neo-box bg-[#F9F7F1] p-6 transition-all" data-purpose="contact-section">
                <div className="grid grid-cols-1 sm:grid-cols-12 gap-2 sm:gap-4 items-start">
                  <label className="sm:col-span-2 text-sm font-bold text-gray-800 sm:pt-2.5" htmlFor="phone-number">
                    전화번호
                  </label>
                  <div className="sm:col-span-5">
                    <input
                      aria-invalid={Boolean(errors.phone)}
                      autoComplete="tel"
                      className="w-full neo-input bg-white font-mono text-sm px-3.5 py-2.5 focus:bg-amber-50/30"
                      id="phone-number"
                      inputMode="numeric"
                      maxLength={13}
                      onChange={(e) => change("phone")(e.target.value)}
                      placeholder="010-0000-0000"
                      type="text"
                      value={values.phone}
                    />
                    <ErrorText>{errors.phone}</ErrorText>
                  </div>
                  <div className="sm:col-span-5 text-xs text-neo-hint font-medium leading-relaxed pl-1 sm:pl-2 sm:pt-3">
                    · 숫자만 입력하면 하이픈이 자동으로 들어가요
                  </div>
                </div>
              </section>
              {/* END: ContactSection */}

              {/* BEGIN: PasswordChangeSection */}
              <section className="neo-box bg-[#F9F7F1] p-6" data-purpose="password-section">
                <h2 className="text-base font-extrabold mb-5 text-neo-black flex items-center gap-2">
                  <span>비밀번호 변경</span>
                </h2>
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                  <div className="lg:col-span-7 space-y-4">
                    <PasswordField
                      autoComplete="current-password"
                      error={errors.currentPassword}
                      id="current-pwd"
                      label="현재 비밀번호"
                      onChange={change("currentPassword")}
                      placeholder="현재 비밀번호 입력 (필수)"
                      value={values.currentPassword}
                    />
                    <PasswordField
                      autoComplete="new-password"
                      error={errors.newPassword}
                      id="new-pwd"
                      label="새 비밀번호"
                      onChange={change("newPassword")}
                      placeholder="바꿀 때만 입력"
                      value={values.newPassword}
                    />
                    <PasswordField
                      autoComplete="new-password"
                      error={errors.passwordConfirm}
                      id="confirm-pwd"
                      label="새 비밀번호 확인"
                      onChange={change("passwordConfirm")}
                      placeholder="새 비밀번호 다시 입력"
                      value={values.passwordConfirm}
                    />
                  </div>
                  <div className="lg:col-span-5 pt-1 lg:pt-2">
                    <div className="p-3.5 bg-[#EEEBE2] rounded-lg border-2 border-[#111] text-xs text-gray-700 space-y-1.5 font-medium leading-relaxed">
                      <p className="flex items-start">
                        <span className="mr-1.5 text-black font-bold">·</span>
                        <span>
                          전화번호만 바꿀 때도 <strong className="text-black">현재 비밀번호</strong>가 필요해요
                        </span>
                      </p>
                      <p className="flex items-start">
                        <span className="mr-1.5 text-black font-bold">·</span>
                        <span>8~12자, 특수기호 _, ., - 만 사용 가능</span>
                      </p>
                      <p className="flex items-start">
                        <span className="mr-1.5 text-black font-bold">·</span>
                        <span>새 비밀번호와 확인이 다르면 에러 표시</span>
                      </p>
                      <p className="flex items-start">
                        <span className="mr-1.5 text-black font-bold">·</span> <span>비밀번호 표시 / 숨기기 가능</span>
                      </p>
                    </div>
                  </div>
                </div>
              </section>
              {/* END: PasswordChangeSection */}

              <ErrorText>{errors.form}</ErrorText>

              {/* BEGIN: ActionButtons */}
              <div className="flex items-center justify-end gap-3 pt-3" data-purpose="form-actions">
                <button
                  className="neo-btn px-6 py-2.5 bg-white text-neo-black font-bold text-sm rounded-lg cursor-pointer hover:bg-gray-50"
                  onClick={() => navigate("/mypage")}
                  type="button"
                >
                  취소
                </button>
                <button
                  className="neo-btn px-7 py-2.5 bg-[#2563EB] text-white font-extrabold text-sm rounded-lg cursor-pointer hover:bg-blue-700 disabled:opacity-60 disabled:cursor-wait"
                  disabled={submitting}
                  type="submit"
                >
                  {submitting ? "저장 중…" : "저장"}
                </button>
              </div>
              {/* END: ActionButtons */}
            </form>
          )}
        </main>
        {/* END: MainContent */}
      </div>
      {completed && <CompleteDialog onClose={() => setCompleted(false)} />}
    </div>
  );
}
